// Validate and normalise before anything else touches the data.
// A malformed payload should fail here with a clear reason, not three
// nodes later inside an API call where the error is unreadable.

const out = [];

for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const errors = [];

  const email = String(b.email ?? '').trim().toLowerCase();
  const name = String(b.name ?? '').trim();
  const message = String(b.message ?? '').trim();
  const source = String(b.source ?? 'unknown').trim();

  // Deliberately permissive. Strict RFC 5322 validation rejects addresses
  // that work, and the cost of a bad address here is one failed email,
  // not a corrupted record.
  if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
    errors.push('invalid or missing email');
  }
  if (!name) errors.push('missing name');
  if (message.length > 5000) errors.push('message too long');

  // Idempotency key. The same form submitted twice within the dedupe
  // window is one lead, not two. Keyed on email plus a coarse time bucket
  // so a genuine second enquiry days later still counts.
  const bucket = Math.floor(Date.now() / (15 * 60 * 1000));
  const dedupeKey = `${email}:${bucket}`;

  out.push({
    json: {
      valid: errors.length === 0,
      errors,
      dedupeKey,
      lead: {
        email,
        name,
        message,
        source,
        received_at: new Date().toISOString(),
      },
    },
  });
}

return out;

// Rule-based scoring, deliberately not an LLM call.
//
// Scoring runs on every single lead, so an API call here would be the
// slowest and most failure-prone step in the workflow, and the one most
// likely to blow a rate limit under a traffic spike. Rules are
// deterministic, instant, free, and a client can read them and disagree
// with them, which matters more than sophistication.

const FREE_EMAIL = new Set([
  'gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com',
  'aol.com', 'icloud.com', 'proton.me', 'protonmail.com',
]);

const BUYING_SIGNALS = [
  'quote', 'pricing', 'price', 'cost', 'budget', 'demo',
  'urgent', 'asap', 'timeline', 'contract', 'proposal',
];

const out = [];

for (const item of $input.all()) {
  const lead = item.json.lead ?? $('Validate and Normalise').first().json.lead;
  const domain = lead.email.split('@')[1] ?? '';
  const text = `${lead.message} ${lead.name}`.toLowerCase();

  let score = 30;
  const reasons = [];

  // A business domain is the single strongest cheap signal that this is
  // a company rather than someone idly enquiring.
  if (domain && !FREE_EMAIL.has(domain)) {
    score += 25;
    reasons.push('business email domain');
  }

  const hits = BUYING_SIGNALS.filter((w) => text.includes(w));
  if (hits.length) {
    score += Math.min(hits.length * 8, 24);
    reasons.push(`buying signals: ${hits.join(', ')}`);
  }

  // Length is a weak proxy for effort. Capped low so a long rambling
  // message cannot outrank a short specific one.
  if (lead.message.length > 200) {
    score += 8;
    reasons.push('detailed message');
  } else if (lead.message.length < 20) {
    score -= 15;
    reasons.push('very short message');
  }

  if (/\b(seo|backlink|guest post|crypto|investment opportunity)\b/.test(text)) {
    score -= 40;
    reasons.push('matches common spam pattern');
  }

  score = Math.max(0, Math.min(100, score));
  const tier = score >= 72 ? 'hot' : score >= 42 ? 'warm' : 'cold';

  out.push({
    json: { ...lead, score, tier, reasons, dedupeKey: item.json.dedupe_key },
  });
}

return out;

