// Merge the model's answer into the lead, and fall back cleanly when it fails.
//
// Three things go wrong with LLMs inside a workflow, and all three are handled
// here rather than being allowed to kill the run:
//   1. the API is down, rate limited, or times out
//   2. it returns prose instead of JSON
//   3. it returns JSON, but not the shape we asked for
//
// In every case the lead still gets stored with its rule-based score. An
// enrichment failure must never cost a lead.

const scored = $('Score Lead').all();
const out = [];

for (let i = 0; i < scored.length; i++) {
  const lead = scored[i].json;
  let enrichment = null;
  let status = 'ok';

  try {
    const resp = $input.all()[i]?.json ?? {};

    // Google returns errors as a 200 with an `error` object, so check that
    // before trusting the body.
    if (resp.error) {
      status = `api_error: ${resp.error.message ?? 'unknown'}`;
      throw new Error(status);
    }

    const text = resp?.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!text) {
      status = 'empty_response';
      throw new Error(status);
    }

    // Models still wrap JSON in markdown fences sometimes, even when asked not
    // to. Strip them before parsing rather than letting JSON.parse throw.
    const cleaned = text.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

    // Set the failure status BEFORE parsing. If JSON.parse throws, the catch
    // block has no way to know why, and the status would wrongly stay 'ok'.
    status = 'parse_error';
    const parsed = JSON.parse(cleaned);
    status = 'ok';

    // Validate the shape. A model that invents fields or returns a string
    // where an enum was asked for is a failure, not a partial success.
    const intents = ['buying', 'researching', 'support', 'spam'];
    const urgencies = ['high', 'medium', 'low'];

    if (!intents.includes(parsed.intent) || !urgencies.includes(parsed.urgency)) {
      status = 'schema_mismatch';
      throw new Error(status);
    }

    enrichment = {
      intent: parsed.intent,
      urgency: parsed.urgency,
      summary: String(parsed.summary ?? '').slice(0, 300),
    };
  } catch (e) {
    // Swallowed on purpose. status already records why, and the lead below is
    // returned with its rule-based score intact.
    enrichment = null;
  }

  // The LLM adjusts the score, it does not replace it. A model having a bad
  // day can move a lead one tier, not invent a hot lead out of nothing.
  let score = lead.score;
  const reasons = [...(lead.reasons ?? [])];

  if (enrichment) {
    if (enrichment.intent === 'buying') { score += 10; reasons.push('AI: buying intent'); }
    if (enrichment.intent === 'spam')   { score -= 30; reasons.push('AI: looks like spam'); }
    if (enrichment.urgency === 'high')  { score += 5;  reasons.push('AI: urgent'); }
  } else {
    reasons.push(`AI enrichment unavailable (${status}) - rule-based score used`);
  }

  score = Math.max(0, Math.min(100, score));

  out.push({
    json: {
      ...lead,
      score,
      reasons,
      tier: score >= 72 ? 'hot' : score >= 42 ? 'warm' : 'cold',
      ai_intent: enrichment?.intent ?? null,
      ai_urgency: enrichment?.urgency ?? null,
      ai_summary: enrichment?.summary ?? null,
      ai_status: status,
    },
  });
}

return out;
